/**
 * 本地编译 API 封装
 *
 * 提供获取编译数据和保存编译结果的 API 调用
 */

import type {
  BatchCompileResult,
  CompileDataResponse,
} from '@/lib/tailwind-compiler';
import { apiClient } from './client';

/**
 * 获取本地编译所需的数据
 */
export function getCompileData(): Promise<CompileDataResponse> {
  return apiClient.get<CompileDataResponse>('/css/compile-data');
}

/**
 * 保存编译结果的请求数据格式
 */
interface SaveCompiledRequest {
  pages: Array<{
    id: number;
    css: string;
    stats: {
      originalSize: number;
      optimizedSize: number;
    };
  }>;
  templates: Array<{
    type: string;
    css: string;
    stats: {
      originalSize: number;
      optimizedSize: number;
    };
  }>;
}

/**
 * 保存编译结果的响应格式
 */
interface SaveCompiledResponse {
  success: boolean;
  stats: {
    totalPages: number;
    totalTemplates: number;
    compiledPages: number;
    compiledTemplates: number;
    errors: Array<{
      page_id?: number;
      template?: string;
      error: string;
    }>;
    originalSize: number;
    optimizedSize: number;
    cdnSize: number;
    compiledItems: Array<{
      page_id?: number;
      page_title?: string;
      template?: string;
      template_name?: string;
      type: string;
      css_size: number;
    }>;
  };
}

/**
 * 保存本地编译结果到服务器（一次性发送所有数据）
 */
export function saveCompiledCSS(
  result: BatchCompileResult
): Promise<SaveCompiledResponse> {
  const requestData: SaveCompiledRequest = {
    pages: result.pages.map((p) => ({
      id: p.id,
      css: p.css,
      stats: p.stats,
    })),
    templates: result.templates.map((t) => ({
      type: t.type,
      css: t.css,
      stats: t.stats,
    })),
  };

  return apiClient.post<SaveCompiledResponse>(
    '/css/save-compiled',
    requestData
  );
}

/**
 * 批次项目类型
 */
type BatchItem =
  | { type: 'page'; data: SaveCompiledRequest['pages'][0] }
  | { type: 'template'; data: SaveCompiledRequest['templates'][0] };

/**
 * 将项目分成批次
 */
function createBatches<T>(items: T[], batchSize: number): T[][] {
  const batches: T[][] = [];
  for (let i = 0; i < items.length; i += batchSize) {
    batches.push(items.slice(i, i + batchSize));
  }
  return batches;
}

/**
 * 创建初始统计信息
 */
function createInitialStats(
  totalPages: number,
  totalTemplates: number
): SaveCompiledResponse['stats'] {
  return {
    totalPages,
    totalTemplates,
    compiledPages: 0,
    compiledTemplates: 0,
    errors: [],
    originalSize: 0,
    optimizedSize: 0,
    cdnSize: 0,
    compiledItems: [],
  };
}

/**
 * 合并响应统计信息
 */
function mergeStats(
  aggregated: SaveCompiledResponse['stats'],
  response: SaveCompiledResponse
): void {
  if (!response.stats) {
    return;
  }

  aggregated.compiledPages += response.stats.compiledPages;
  aggregated.compiledTemplates += response.stats.compiledTemplates;
  aggregated.errors.push(...response.stats.errors);
  aggregated.originalSize += response.stats.originalSize;
  aggregated.optimizedSize += response.stats.optimizedSize;
  aggregated.compiledItems.push(...response.stats.compiledItems);
}

/**
 * 记录批次错误
 */
function recordBatchError(
  aggregated: SaveCompiledResponse['stats'],
  batch: BatchItem[],
  batchIndex: number,
  error: unknown
): void {
  const errorMessage = error instanceof Error ? error.message : String(error);

  for (const item of batch) {
    if (item.type === 'page') {
      aggregated.errors.push({
        page_id: item.data.id,
        error: `Batch ${batchIndex + 1} failed: ${errorMessage}`,
      });
    } else {
      aggregated.errors.push({
        template: item.data.type,
        error: `Batch ${batchIndex + 1} failed: ${errorMessage}`,
      });
    }
  }
}

/**
 * 降级序列：10 → 5 → 3 → 1
 */
const DEGRADATION_SEQUENCE = [10, 5, 3, 1];

/**
 * 检查错误是否为 403 错误
 */
function is403Error(error: unknown): boolean {
  if (error instanceof Error) {
    return error.message.includes('403') || error.message.includes('Forbidden');
  }
  return false;
}

/**
 * 获取下一个降级批次大小
 */
function getNextBatchSize(currentSize: number): number | null {
  // 找到当前批次大小在序列中的位置
  const currentIndex = DEGRADATION_SEQUENCE.findIndex(
    (size) => size <= currentSize
  );

  if (currentIndex === -1) {
    // 当前大小比序列最大值还大，降级到序列第一个
    return DEGRADATION_SEQUENCE[0];
  }

  // 如果已经是最后一个（1），不再降级
  if (currentIndex === DEGRADATION_SEQUENCE.length - 1) {
    return null;
  }

  // 返回序列中下一个更小的值
  return DEGRADATION_SEQUENCE[currentIndex + 1];
}

/**
 * 处理单个批次（带降级重试）
 */
async function processBatch(
  batch: BatchItem[],
  aggregated: SaveCompiledResponse['stats'],
  batchIndex: number,
  currentBatchSize?: number
): Promise<void> {
  const batchPages = batch
    .filter((item) => item.type === 'page')
    .map((item) => item.data as SaveCompiledRequest['pages'][0]);

  const batchTemplates = batch
    .filter((item) => item.type === 'template')
    .map((item) => item.data as SaveCompiledRequest['templates'][0]);

  const batchData: SaveCompiledRequest = {
    pages: batchPages,
    templates: batchTemplates,
  };

  try {
    const response = await apiClient.post<SaveCompiledResponse>(
      '/css/save-compiled',
      batchData
    );
    mergeStats(aggregated, response);
  } catch (error) {
    // 如果是 403 错误且批次大于 1，尝试降级重试
    if (is403Error(error) && batch.length > 1) {
      const actualBatchSize = currentBatchSize || batch.length;
      const nextBatchSize = getNextBatchSize(actualBatchSize);

      if (nextBatchSize !== null) {
        // 降级：拆分成更小的批次重试
        const smallerBatches = createBatches(batch, nextBatchSize);

        for (const smallerBatch of smallerBatches) {
          await processBatch(
            smallerBatch,
            aggregated,
            batchIndex,
            nextBatchSize // 传递降级后的批次大小
          );
        }
      } else {
        // 已经降级到 1 还是失败，记录错误
        recordBatchError(aggregated, batch, batchIndex, error);
      }
    } else {
      // 其他错误或已经是单个项目，记录错误
      recordBatchError(aggregated, batch, batchIndex, error);
    }
  }
}

/**
 * 分批保存编译结果（用于绕过 WAF 限制）
 *
 * 将所有页面和模板分成小批次，依次发送
 * 每批最多包含 batchSize 个项目
 *
 * @param result 编译结果
 * @param batchSize 每批次的数量，默认 3
 * @param onProgress 进度回调 (current, total)
 */
export async function saveCompiledCSSInBatches(
  result: BatchCompileResult,
  batchSize = 3,
  onProgress?: (current: number, total: number) => void
): Promise<SaveCompiledResponse> {
  const pages = result.pages.map((p) => ({
    id: p.id,
    css: p.css,
    stats: p.stats,
  }));

  const templates = result.templates.map((t) => ({
    type: t.type,
    css: t.css,
    stats: t.stats,
  }));

  // 合并所有项目
  const allItems: BatchItem[] = [
    ...pages.map((p) => ({ type: 'page' as const, data: p })),
    ...templates.map((t) => ({ type: 'template' as const, data: t })),
  ];

  const batches = createBatches(allItems, batchSize);
  const aggregatedStats = createInitialStats(pages.length, templates.length);

  // 依次发送每个批次
  for (let i = 0; i < batches.length; i++) {
    await processBatch(batches[i], aggregatedStats, i);

    if (onProgress) {
      onProgress(i + 1, batches.length);
    }
  }

  // 计算 CDN 总大小
  const totalCompiledItems =
    aggregatedStats.compiledPages + aggregatedStats.compiledTemplates;
  if (totalCompiledItems > 0) {
    aggregatedStats.cdnSize = 342_016 * totalCompiledItems;
  }

  return {
    success: aggregatedStats.errors.length === 0,
    stats: aggregatedStats,
  };
}

/**
 * 清理旧缓存
 */
export function clearLegacyCache(): Promise<{ success: boolean }> {
  return apiClient.post('/css/clear-cache');
}
