/**
 * 本地 Tailwind CSS 编译 Hook
 *
 * 管理本地编译的状态和流程
 */

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useCallback, useState } from 'react';
import {
  clearLegacyCache,
  getCompileData,
  saveCompiledCSSInBatches,
} from '@/api/local-compile';
import { type BatchCompileResult, compileAll } from '@/lib/tailwind-compiler';

/** 是否启用调试模式 */
const DEBUG_ENABLED =
  typeof window !== 'undefined' && localStorage.getItem('zeroy_debug') === '1';

/** 调试日志 */
function debugLog(message: string, data?: unknown) {
  if (!DEBUG_ENABLED) {
    return;
  }

  const prefix = '[ZeroY LocalCompiler Hook]';
  // eslint-disable-next-line no-console
  console.groupCollapsed(`${prefix} ${message}`);
  if (data !== undefined) {
    // eslint-disable-next-line no-console
    console.log(data);
  }
  // eslint-disable-next-line no-console
  console.groupEnd();
}

export interface LocalCompilerState {
  /** 是否正在编译 */
  isCompiling: boolean;
  /** 编译进度 0-100 */
  progress: number;
  /** 当前正在编译的项目名称 */
  currentItem: string;
  /** 当前项目索引 */
  currentIndex: number;
  /** 总项目数 */
  totalItems: number;
  /** 编译阶段 */
  stage: 'idle' | 'fetching' | 'compiling' | 'saving' | 'done' | 'error';
  /** 错误信息 */
  error: string | null;
}

export interface LocalCompilerResult {
  /** 编译状态 */
  state: LocalCompilerState;
  /** 编译结果 */
  result: BatchCompileResult | null;
  /** 开始编译 */
  compile: () => Promise<BatchCompileResult | null>;
  /** 重置状态 */
  reset: () => void;
}

const initialState: LocalCompilerState = {
  isCompiling: false,
  progress: 0,
  currentItem: '',
  currentIndex: 0,
  totalItems: 0,
  stage: 'idle',
  error: null,
};

/**
 * 本地编译 Hook
 */
export function useLocalCompiler(): LocalCompilerResult {
  const queryClient = useQueryClient();
  const [state, setState] = useState<LocalCompilerState>(initialState);
  const [result, setResult] = useState<BatchCompileResult | null>(null);

  // 编译 mutation
  const compileMutation = useMutation({
    mutationFn: async (): Promise<BatchCompileResult> => {
      debugLog('开始本地编译流程');

      // 阶段 1: 清理旧缓存
      setState((prev) => ({
        ...prev,
        isCompiling: true,
        stage: 'fetching',
        progress: 5,
        currentItem: '清理旧缓存...',
        error: null,
      }));

      await clearLegacyCache();
      debugLog('旧缓存已清理');

      // 阶段 2: 获取编译数据
      setState((prev) => ({
        ...prev,
        progress: 10,
        currentItem: '获取编译数据...',
      }));

      const compileData = await getCompileData();

      debugLog('获取到编译数据', {
        pagesCount: compileData.pages.length,
        templatesCount: compileData.templates.length,
        designSystemHtmlLength: compileData.designSystemHtml?.length || 0,
        hasHeader: !!compileData.commonTemplates?.header,
        hasFooter: !!compileData.commonTemplates?.footer,
        safelistLength: compileData.safelist?.length || 0,
      });

      // 输出设计系统 HTML 的详细信息
      if (compileData.designSystemHtml) {
        debugLog('设计系统 HTML 详情', {
          fullContent: compileData.designSystemHtml,
          containsTailwindConfig:
            compileData.designSystemHtml.includes('tailwind.config'),
          containsColors: compileData.designSystemHtml.includes('colors'),
          containsBrand: compileData.designSystemHtml.includes('brand'),
        });
      } else {
        debugLog('⚠️ 设计系统为空，将使用默认 Tailwind 配置');
      }

      const totalItems =
        compileData.pages.length + compileData.templates.length;

      if (totalItems === 0) {
        throw new Error('没有找到需要编译的页面或模板');
      }

      // 阶段 3: 本地编译
      setState((prev) => ({
        ...prev,
        stage: 'compiling',
        progress: 15,
        totalItems,
        currentItem: '开始编译...',
      }));

      debugLog('开始本地 Tailwind 编译', { totalItems });

      const compileResult = await compileAll(
        compileData,
        { minify: true },
        (progress, currentItem, currentIndex, total) => {
          // 编译进度映射到 15-85 区间
          const mappedProgress = 15 + Math.round((progress / 100) * 70);
          setState((prev) => ({
            ...prev,
            progress: mappedProgress,
            currentItem,
            currentIndex,
            totalItems: total,
          }));
        }
      );

      debugLog('编译完成', {
        compiledPages: compileResult.stats.compiledPages,
        compiledTemplates: compileResult.stats.compiledTemplates,
        errorsCount: compileResult.errors.length,
        totalOptimizedSize: compileResult.stats.totalOptimizedSize,
      });

      // 输出每个编译结果的 CSS 大小
      if (compileResult.pages.length > 0) {
        debugLog(
          '页面编译结果',
          compileResult.pages.map((p) => ({
            id: p.id,
            cssSize: p.css.length,
            cssPreview: p.css.substring(0, 500),
          }))
        );
      }

      if (compileResult.templates.length > 0) {
        debugLog(
          '模板编译结果',
          compileResult.templates.map((t) => ({
            type: t.type,
            cssSize: t.css.length,
            cssPreview: t.css.substring(0, 500),
          }))
        );
      }

      if (compileResult.errors.length > 0) {
        debugLog('编译错误', compileResult.errors);
      }

      // 阶段 4: 保存编译结果（分批保存）
      setState((prev) => ({
        ...prev,
        stage: 'saving',
        progress: 85,
        currentItem: '保存编译结果...',
      }));

      debugLog('开始分批保存编译结果');

      await saveCompiledCSSInBatches(
        compileResult,
        10, // 每批 10 个文件（遇到 403 会自动降级：10→5→3→1）
        (current, total) => {
          // 保存进度映射到 85-95 区间
          const saveProgress = 85 + Math.round((current / total) * 10);
          setState((prev) => ({
            ...prev,
            progress: saveProgress,
            currentItem: `保存编译结果 (${current}/${total} 批次)...`,
          }));
          debugLog(`保存进度: ${current}/${total} 批次`);
        }
      );

      debugLog('编译结果已保存（分批完成）');

      // 完成
      setState((prev) => ({
        ...prev,
        stage: 'done',
        progress: 100,
        currentItem: '编译完成',
        isCompiling: false,
      }));

      return compileResult;
    },
    onSuccess: (data) => {
      setResult(data);
      // 刷新 CSS 统计数据
      queryClient.invalidateQueries({ queryKey: ['css-compiler-stats'] });
      queryClient.invalidateQueries({ queryKey: ['settings'] });
    },
    onError: (error: Error) => {
      setState((prev) => ({
        ...prev,
        stage: 'error',
        isCompiling: false,
        error: error.message,
      }));
    },
  });

  const compile = useCallback(async (): Promise<BatchCompileResult | null> => {
    try {
      const res = await compileMutation.mutateAsync();
      return res;
    } catch {
      return null;
    }
  }, [compileMutation]);

  const reset = useCallback(() => {
    setState(initialState);
    setResult(null);
  }, []);

  return {
    state,
    result,
    compile,
    reset,
  };
}
