/**
 * 本地 Tailwind CSS 编译器
 *
 * 使用 @mhsdesign/jit-browser-tailwindcss 在浏览器端编译 Tailwind CSS
 * 无需调用远程 Worker，实现离线编译能力
 */

import {
  filterCustomCSS,
  parseDesignSystem,
  parseDesignSystemConfig,
  type TailwindConfig,
} from './tailwind-config-parser';

// ============================================================================
// 调试配置
// ============================================================================

/** 是否启用调试模式（浏览器控制台） */
const DEBUG_ENABLED =
  typeof window !== 'undefined' && localStorage.getItem('zeroy_debug') === '1';

/** 编译重试次数 */
const COMPILE_MAX_RETRIES = 1;

/** 正则表达式 - 顶层定义以提升性能 */
const CLASS_ATTR_REGEX = /class\s*=\s*["']([^"']+)["']/gi;
const WHITESPACE_REGEX = /\s+/;
const CUSTOM_COLOR_PATTERN =
  /^(?:hover:|focus:|active:|group-hover:)?(?:text|bg|border|ring|from|to|via)-(?:brand|primary|secondary|accent)-\d+$/;
const COLOR_NAME_REGEX = /(?:text|bg|border|ring|from|to|via)-([a-z]+)-\d+/;

/** 带重试的异步函数执行 */
async function withRetry<T>(
  fn: () => Promise<T>,
  maxRetries: number = COMPILE_MAX_RETRIES
): Promise<T> {
  let lastError: Error | null = null;
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error as Error;
      if (attempt < maxRetries) {
        debugLog('retry', `重试 (${attempt + 1}/${maxRetries})`, error);
      }
    }
  }
  throw lastError;
}

/** 调试日志 */
function debugLog(category: string, message: string, data?: unknown) {
  if (!DEBUG_ENABLED) {
    return;
  }

  const timestamp = new Date().toISOString();
  const prefix = `[ZeroY Compiler ${timestamp}] [${category}]`;

  // eslint-disable-next-line no-console
  console.groupCollapsed(`${prefix} ${message}`);
  if (data !== undefined) {
    // eslint-disable-next-line no-console
    console.log(data);
  }
  // eslint-disable-next-line no-console
  console.groupEnd();
}

/** 提取 HTML 中使用的 Tailwind 类（用于调试） */
function extractTailwindClasses(html: string): string[] {
  // 重置正则状态
  CLASS_ATTR_REGEX.lastIndex = 0;
  const classes = new Set<string>();

  let match = CLASS_ATTR_REGEX.exec(html);
  while (match !== null) {
    const classValue = match[1];
    for (const cls of classValue.split(WHITESPACE_REGEX)) {
      if (cls.trim()) {
        classes.add(cls.trim());
      }
    }
    match = CLASS_ATTR_REGEX.exec(html);
  }

  return [...classes].sort();
}

/** 过滤出自定义颜色类（如 brand-*） */
function filterCustomColorClasses(classes: string[]): string[] {
  return classes.filter((cls) => CUSTOM_COLOR_PATTERN.test(cls));
}

/** 调试: 检查并记录配置信息 */
function debugLogConfig(
  parsedConfig: TailwindConfig
): Record<string, string | Record<string, string>> | undefined {
  debugLog('config', '解析后的 Tailwind 配置', parsedConfig);

  const themeColors = parsedConfig.theme?.extend?.colors;
  if (themeColors) {
    debugLog('config', '自定义颜色配置', themeColors);
  } else {
    debugLog('config', '警告: 未发现自定义颜色配置', {
      theme: parsedConfig.theme,
    });
  }
  return themeColors;
}

/** 调试: 检查缺失的颜色定义 */
function debugLogMissingColors(
  customColorClasses: string[],
  themeColors: Record<string, string | Record<string, string>> | undefined
) {
  if (customColorClasses.length === 0) {
    return;
  }

  debugLog('classes', '发现自定义颜色类', customColorClasses);

  const missingColors: string[] = [];
  for (const cls of customColorClasses) {
    const colorMatch = cls.match(COLOR_NAME_REGEX);
    if (colorMatch) {
      const colorName = colorMatch[1];
      if (!(themeColors && colorName in themeColors)) {
        missingColors.push(cls);
      }
    }
  }

  if (missingColors.length > 0) {
    debugLog('classes', '警告: 以下颜色类未在配置中定义', missingColors);
  }
}

/** 收集所有 HTML 内容用于调试 */
function collectAllHtml(data: CompileDataResponse): string {
  return [
    data.designSystemHtml || '',
    data.commonTemplates.header || '',
    data.commonTemplates.footer || '',
    data.safelist || '',
    ...data.pages.map((p) => p.html),
    ...data.templates.map((t) => t.html),
  ].join('\n');
}

// ============================================================================
// 类型定义
// ============================================================================

export interface CompileOptions {
  /** 是否压缩 CSS */
  minify?: boolean;
}

export interface CompileResult {
  /** 编译后的 CSS */
  css: string;
  /** 编译统计 */
  stats: {
    /** 原始 HTML 大小 */
    originalSize: number;
    /** 编译后 CSS 大小 */
    optimizedSize: number;
  };
}

export interface PageCompileItem {
  /** 页面 ID */
  id: number;
  /** 页面标题 */
  title: string;
  /** 页面类型 */
  type: 'page' | 'post';
  /** 页面 HTML 内容 */
  html: string;
  /** 是否排除页眉页脚 */
  excludeHeaderFooter: boolean;
}

export interface TemplateCompileItem {
  /** 模板类型 */
  type: string;
  /** 模板名称 */
  name: string;
  /** 模板 HTML 内容 */
  html: string;
}

export interface CommonTemplates {
  header?: string;
  footer?: string;
}

export interface CompileDataResponse {
  /** 设计系统 HTML */
  designSystemHtml: string;
  /** 已提取的 Tailwind 配置 */
  extractedTailwindConfig?: string;
  /** 公共模板 */
  commonTemplates: CommonTemplates;
  /** 待编译的页面 */
  pages: PageCompileItem[];
  /** 待编译的模板 */
  templates: TemplateCompileItem[];
  /** Safelist HTML */
  safelist: string;
}

export interface PageCompileResult {
  id: number;
  css: string;
  stats: {
    originalSize: number;
    optimizedSize: number;
  };
}

export interface TemplateCompileResult {
  type: string;
  css: string;
  stats: {
    originalSize: number;
    optimizedSize: number;
  };
}

export interface BatchCompileResult {
  pages: PageCompileResult[];
  templates: TemplateCompileResult[];
  errors: Array<{
    itemId: string | number;
    itemName: string;
    itemType: 'page' | 'template';
    error: string;
  }>;
  stats: {
    totalPages: number;
    totalTemplates: number;
    compiledPages: number;
    compiledTemplates: number;
    totalOriginalSize: number;
    totalOptimizedSize: number;
  };
}

export type ProgressCallback = (
  progress: number,
  currentItem: string,
  itemIndex: number,
  totalItems: number
) => void;

let tailwindModulePromise: Promise<
  typeof import('@mhsdesign/jit-browser-tailwindcss')
> | null = null;

function buildBaseCss(customCSS = ''): string {
  const base = `@tailwind base;
    @tailwind components;
    @tailwind utilities;`;
  return customCSS ? `${base}\n${customCSS}` : base;
}

// ============================================================================
// 编译器实现
// ============================================================================

/**
 * 创建 Tailwind 编译实例
 */
async function createCompilerInstance(config: TailwindConfig) {
  if (!tailwindModulePromise) {
    tailwindModulePromise = import('@mhsdesign/jit-browser-tailwindcss');
  }

  const { createTailwindcss } = await tailwindModulePromise;

  // 使用类型断言绕过严格类型检查
  // 我们的配置格式与库兼容，但 TypeScript 无法自动推断
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  return createTailwindcss({
    tailwindConfig: config as any,
  });
}

/**
 * 简单的 CSS 压缩
 */
function minifyCSS(css: string): string {
  return css
    .replace(/\/\*[\s\S]*?\*\//g, '') // 移除注释
    .replace(/\s+/g, ' ') // 移除多余空白
    .replace(/\s*([{}:;,>+~])\s*/g, '$1') // 移除选择器前后空白
    .replace(/;}/g, '}') // 移除最后一个分号
    .trim();
}

/**
 * 组装页面 HTML
 * 与 PHP 端 ZeroY_CSS_Compile_Strategy_Service::build_page_html 逻辑一致
 */
function assemblePageHtml(
  page: PageCompileItem,
  commonTemplates: CommonTemplates,
  safelist: string
): string {
  const parts: string[] = [];

  // 添加页眉（除非排除）
  if (!page.excludeHeaderFooter && commonTemplates.header) {
    parts.push(commonTemplates.header);
  }

  // 添加页面内容
  if (page.html) {
    parts.push(page.html);
  }

  // 添加页脚（除非排除）
  if (!page.excludeHeaderFooter && commonTemplates.footer) {
    parts.push(commonTemplates.footer);
  }

  // 添加 safelist
  if (safelist) {
    parts.push(safelist);
  }

  return parts.join('\n');
}

/**
 * 组装模板 HTML
 * 与 PHP 端 ZeroY_CSS_Compile_Strategy_Service::build_template_html 逻辑一致
 */
function assembleTemplateHtml(
  template: TemplateCompileItem,
  commonTemplates: CommonTemplates,
  safelist: string
): string {
  const parts: string[] = [];

  // 页眉和页脚模板只编译自己
  if (template.type === 'header' || template.type === 'footer') {
    if (template.html) {
      parts.push(template.html);
    }
    if (safelist) {
      parts.push(safelist);
    }
    return parts.join('\n');
  }

  // 其他模板包含页眉页脚
  if (commonTemplates.header) {
    parts.push(commonTemplates.header);
  }

  if (template.html) {
    parts.push(template.html);
  }

  if (commonTemplates.footer) {
    parts.push(commonTemplates.footer);
  }

  if (safelist) {
    parts.push(safelist);
  }

  return parts.join('\n');
}

/**
 * 编译单个 HTML 内容
 */
export async function compileTailwindCSS(
  html: string,
  designSystemHtml?: string,
  options: CompileOptions = {}
): Promise<CompileResult> {
  const originalSize = html.length;

  if (!html.trim()) {
    return {
      css: '',
      stats: {
        originalSize: 0,
        optimizedSize: 0,
      },
    };
  }

  // 解析设计系统配置和自定义 CSS
  const parsedDesignSystem = parseDesignSystem(designSystemHtml || '');
  const customCSS = filterCustomCSS(html, parsedDesignSystem.customCSSMap);

  // 创建编译实例
  const tailwind = await createCompilerInstance(parsedDesignSystem.config);

  // 生成 CSS - 包含 base（preflight）、components（container 等）和 utilities
  const css = await tailwind.generateStylesFromContent(
    buildBaseCss(customCSS),
    [html, designSystemHtml || '']
  );

  // 压缩（如果需要）
  const finalCss = options.minify ? minifyCSS(css) : css;

  return {
    css: finalCss,
    stats: {
      originalSize,
      optimizedSize: finalCss.length,
    },
  };
}

/** 编译器上下文，用于批量编译 */
interface CompileContext {
  tailwind: Awaited<ReturnType<typeof createCompilerInstance>>;
  designSystemHtml: string;
  customCSSMap?: Map<string, string>;
  commonTemplates: CommonTemplates;
  safelist: string;
  options: CompileOptions;
}

/**
 * 编译单个页面
 */
async function compilePage(
  page: PageCompileItem,
  ctx: CompileContext
): Promise<PageCompileResult> {
  const assembledHtml = assemblePageHtml(
    page,
    ctx.commonTemplates,
    ctx.safelist
  );
  const customCSS = filterCustomCSS(assembledHtml, ctx.customCSSMap);
  const css = await ctx.tailwind.generateStylesFromContent(
    buildBaseCss(customCSS),
    [assembledHtml, ctx.designSystemHtml]
  );
  const finalCss = ctx.options.minify ? minifyCSS(css) : css;

  return {
    id: page.id,
    css: finalCss,
    stats: {
      originalSize: assembledHtml.length,
      optimizedSize: finalCss.length,
    },
  };
}

/**
 * 编译单个模板
 */
async function compileTemplate(
  template: TemplateCompileItem,
  ctx: CompileContext
): Promise<TemplateCompileResult> {
  const assembledHtml = assembleTemplateHtml(
    template,
    ctx.commonTemplates,
    ctx.safelist
  );
  const customCSS = filterCustomCSS(assembledHtml, ctx.customCSSMap);
  const css = await ctx.tailwind.generateStylesFromContent(
    buildBaseCss(customCSS),
    [assembledHtml, ctx.designSystemHtml]
  );
  const finalCss = ctx.options.minify ? minifyCSS(css) : css;

  return {
    type: template.type,
    css: finalCss,
    stats: {
      originalSize: assembledHtml.length,
      optimizedSize: finalCss.length,
    },
  };
}

/** 编译所有页面 */
async function compileAllPages(
  pages: PageCompileItem[],
  ctx: CompileContext,
  result: BatchCompileResult,
  onProgress: ProgressCallback | undefined,
  totalItems: number,
  startIndex: number
): Promise<number> {
  let completedItems = startIndex;

  for (const page of pages) {
    const itemName = page.title || `页面 #${page.id}`;
    onProgress?.(
      Math.round((completedItems / totalItems) * 100),
      itemName,
      completedItems + 1,
      totalItems
    );

    try {
      const pageResult = await withRetry(() => compilePage(page, ctx));
      result.pages.push(pageResult);
      result.stats.compiledPages++;
      result.stats.totalOriginalSize += pageResult.stats.originalSize;
      result.stats.totalOptimizedSize += pageResult.stats.optimizedSize;
    } catch (error) {
      result.errors.push({
        itemId: page.id,
        itemName,
        itemType: 'page',
        error: error instanceof Error ? error.message : String(error),
      });
    }

    completedItems++;
  }

  return completedItems;
}

/** 编译所有模板 */
async function compileAllTemplates(
  templates: TemplateCompileItem[],
  ctx: CompileContext,
  result: BatchCompileResult,
  onProgress: ProgressCallback | undefined,
  totalItems: number,
  startIndex: number
): Promise<void> {
  let completedItems = startIndex;

  for (const template of templates) {
    const itemName = template.name || `模板: ${template.type}`;
    onProgress?.(
      Math.round((completedItems / totalItems) * 100),
      itemName,
      completedItems + 1,
      totalItems
    );

    try {
      const templateResult = await withRetry(() =>
        compileTemplate(template, ctx)
      );
      result.templates.push(templateResult);
      result.stats.compiledTemplates++;
      result.stats.totalOriginalSize += templateResult.stats.originalSize;
      result.stats.totalOptimizedSize += templateResult.stats.optimizedSize;
    } catch (error) {
      result.errors.push({
        itemId: template.type,
        itemName,
        itemType: 'template',
        error: error instanceof Error ? error.message : String(error),
      });
    }

    completedItems++;
  }
}

// ============================================================================
// 单页编译支持
// ============================================================================

export interface SinglePageCompileResult {
  /** 编译后的 CSS */
  css: string;
  /** 编译统计 */
  stats: {
    originalSize: number;
    optimizedSize: number;
  };
}

export interface HeaderFooterData {
  header: string;
  footer: string;
  safelist: string;
  header_footer_hash: string;
  design_system_hash: string;
}

/** 编译器就绪状态 */
let compilerInitialized = false;
let warmupPromise: Promise<void> | null = null;

/**
 * 预热编译器（内部实现）
 */
async function doWarmup(): Promise<void> {
  try {
    // 获取设计系统配置（使用完整 HTML，与 compileAll 保持一致）
    const designSystemHtml = window.zeroyEditor?.designSystemHtml || '';

    // 解析配置
    const config = parseDesignSystemConfig(designSystemHtml);

    // 创建编译器实例进行预热（编译空内容）
    const tailwind = await createCompilerInstance(config);
    await tailwind.generateStylesFromContent(buildBaseCss(), [
      '<div class="hidden"></div>',
      designSystemHtml,
    ]);

    compilerInitialized = true;
    debugLog('warmup', '编译器预热完成');
  } catch (error) {
    debugLog('warmup', '编译器预热失败', error);
    throw error;
  } finally {
    warmupPromise = null;
  }
}

/**
 * 预热编译器
 * 预先初始化 Tailwind JIT 编译器，加载设计系统配置
 */
export function warmup(): Promise<void> {
  if (compilerInitialized) {
    return Promise.resolve();
  }

  // 防止重复预热
  if (warmupPromise) {
    return warmupPromise;
  }

  warmupPromise = doWarmup();
  return warmupPromise;
}

/**
 * 检查编译器是否就绪
 */
export function isReady(): boolean {
  return compilerInitialized;
}

/**
 * 编译单个页面的 CSS
 *
 * @param pageHtml 页面 HTML 内容
 * @param headerFooterData 页眉页脚数据（从 API 获取）
 * @param options 编译选项
 */
export async function compileSinglePage(
  pageHtml: string,
  headerFooterData: HeaderFooterData | null,
  options: CompileOptions = {}
): Promise<SinglePageCompileResult | null> {
  try {
    // 组装完整 HTML
    let fullHtml = pageHtml;

    if (headerFooterData) {
      const { header, footer, safelist } = headerFooterData;
      // 组装：header + 页面内容 + footer + safelist
      fullHtml = (header || '') + pageHtml + (footer || '');

      // 添加 safelist（与批量编译保持一致）
      if (safelist) {
        fullHtml += `\n${safelist}`;
      }
    }

    // 获取设计系统配置（使用完整 HTML，与 compileAll 保持一致）
    const designSystemHtml = window.zeroyEditor?.designSystemHtml || '';

    // 解析配置并创建编译器
    const parsedDesignSystem = parseDesignSystem(designSystemHtml);
    const customCSS = filterCustomCSS(
      fullHtml,
      parsedDesignSystem.customCSSMap
    );
    const tailwind = await createCompilerInstance(parsedDesignSystem.config);

    // 生成 CSS
    const css = await tailwind.generateStylesFromContent(
      buildBaseCss(customCSS),
      [fullHtml, designSystemHtml]
    );

    // 压缩（如果需要）
    const finalCss = options.minify !== false ? minifyCSS(css) : css;

    debugLog('compileSinglePage', '单页编译完成', {
      originalSize: fullHtml.length,
      optimizedSize: finalCss.length,
    });

    return {
      css: finalCss,
      stats: {
        originalSize: fullHtml.length,
        optimizedSize: finalCss.length,
      },
    };
  } catch (error) {
    debugLog('compileSinglePage', '单页编译失败', error);
    return null;
  }
}

// ============================================================================
// 批量编译
// ============================================================================

/**
 * 批量编译所有页面和模板
 */
export async function compileAll(
  data: CompileDataResponse,
  options: CompileOptions = {},
  onProgress?: ProgressCallback
): Promise<BatchCompileResult> {
  debugLog('compileAll', '开始批量编译', {
    pagesCount: data.pages.length,
    templatesCount: data.templates.length,
    designSystemHtmlLength: data.designSystemHtml?.length || 0,
    options,
  });

  const result: BatchCompileResult = {
    pages: [],
    templates: [],
    errors: [],
    stats: {
      totalPages: data.pages.length,
      totalTemplates: data.templates.length,
      compiledPages: 0,
      compiledTemplates: 0,
      totalOriginalSize: 0,
      totalOptimizedSize: 0,
    },
  };

  const totalItems = data.pages.length + data.templates.length;

  // 解析设计系统配置并记录调试信息
  const parsedDesignSystem = parseDesignSystem(data.designSystemHtml || '');
  const themeColors = debugLogConfig(parsedDesignSystem.config);

  // 收集并分析所有使用的类（调试用）
  const allHtml = collectAllHtml(data);
  const allClasses = extractTailwindClasses(allHtml);
  const customColorClasses = filterCustomColorClasses(allClasses);

  debugLog('classes', '所有使用的 Tailwind 类', {
    total: allClasses.length,
    sample: allClasses.slice(0, 50),
  });

  debugLogMissingColors(customColorClasses, themeColors);

  // 创建编译上下文
  const ctx: CompileContext = {
    tailwind: await createCompilerInstance(parsedDesignSystem.config),
    designSystemHtml: data.designSystemHtml || '',
    customCSSMap: parsedDesignSystem.customCSSMap,
    commonTemplates: data.commonTemplates,
    safelist: data.safelist,
    options,
  };

  // 编译页面和模板
  const completedPages = await compileAllPages(
    data.pages,
    ctx,
    result,
    onProgress,
    totalItems,
    0
  );
  await compileAllTemplates(
    data.templates,
    ctx,
    result,
    onProgress,
    totalItems,
    completedPages
  );

  // 最终进度
  onProgress?.(100, '编译完成', totalItems, totalItems);

  debugLog('compileAll', '编译完成', {
    compiledPages: result.stats.compiledPages,
    compiledTemplates: result.stats.compiledTemplates,
    errors: result.errors.length,
    totalOptimizedSize: result.stats.totalOptimizedSize,
  });

  return result;
}
