/**
 * Tailwind 配置解析器
 *
 * 从设计系统 HTML 中提取 Tailwind 配置
 * 与 PHP 端 ZeroY_Design_System_Extractor 逻辑保持一致
 */

import { parseCSSRules } from './css-parser';

// 预编译正则表达式，提升性能
const SCRIPT_REGEX = /<script[^>]*>([\s\S]*?)<\/script>/gi;
const CONFIG_REGEX = /tailwind\.config\s*=\s*(\{[\s\S]*)/i;
const WHITESPACE_REGEX = /\s+/;

/** 是否启用调试模式 */
const DEBUG_ENABLED =
  typeof window !== 'undefined' && localStorage.getItem('zeroy_debug') === '1';

/** 调试日志 */
function debugLog(message: string, data?: unknown) {
  if (!DEBUG_ENABLED) {
    return;
  }

  const prefix = '[ZeroY ConfigParser]';
  // eslint-disable-next-line no-console
  console.groupCollapsed(`${prefix} ${message}`);
  if (data !== undefined) {
    // eslint-disable-next-line no-console
    console.log(data);
  }
  // eslint-disable-next-line no-console
  console.groupEnd();
}

export interface TailwindThemeExtend {
  colors?: Record<string, string | Record<string, string>>;
  fontFamily?: Record<string, string[]>;
  fontSize?: Record<string, string | [string, string]>;
  spacing?: Record<string, string>;
  borderRadius?: Record<string, string>;
  boxShadow?: Record<string, string>;
  [key: string]: unknown;
}

export interface TailwindTheme {
  extend?: TailwindThemeExtend;
  [key: string]: unknown;
}

export interface TailwindConfig {
  theme?: TailwindTheme;
  corePlugins?: {
    preflight?: boolean;
    [key: string]: unknown;
  };
  plugins?: unknown[];
  [key: string]: unknown;
}

export interface ParsedDesignSystem {
  config: TailwindConfig;
  customCSS?: string;
  customCSSMap?: Map<string, string>;
  globalCustomCSS?: string;
}

/** 字符串引号字符 */
const STRING_CHARS = new Set(['"', "'", '`']);

/**
 * 查找平衡的闭合大括号位置
 * 与 PHP 端 find_balanced_closing_brace 逻辑一致
 */
function findBalancedClosingBrace(str: string): number {
  const state = {
    braceCount: 0,
    inString: false,
    stringChar: '',
    escaped: false,
  };

  for (let i = 0; i < str.length; i++) {
    const result = processChar(str[i], state);
    if (result !== -1) {
      return i;
    }
  }

  return -1;
}

/**
 * 处理单个字符，更新状态
 * @returns 如果找到平衡的闭合括号返回其位置标记(0)，否则返回 -1
 */
function processChar(
  char: string,
  state: {
    braceCount: number;
    inString: boolean;
    stringChar: string;
    escaped: boolean;
  }
): number {
  // 处理转义字符
  if (state.escaped) {
    state.escaped = false;
    return -1;
  }

  if (char === '\\') {
    state.escaped = true;
    return -1;
  }

  // 处理字符串状态
  if (!state.inString && STRING_CHARS.has(char)) {
    state.inString = true;
    state.stringChar = char;
    return -1;
  }

  if (state.inString && char === state.stringChar) {
    state.inString = false;
    state.stringChar = '';
    return -1;
  }

  // 处理大括号（仅在非字符串状态下）
  if (state.inString) {
    return -1;
  }

  if (char === '{') {
    state.braceCount++;
  } else if (char === '}') {
    state.braceCount--;
    if (state.braceCount === 0) {
      return 0; // 找到匹配的闭合括号
    }
  }

  return -1;
}

/**
 * 从设计系统 HTML 中提取 Tailwind 配置
 *
 * 支持的格式：
 * 1. <script>tailwind.config = { ... }</script>
 * 2. <script type="text/javascript">tailwind.config = { ... }</script>
 *
 * @param designSystemHtml - 设计系统 HTML
 * @returns 解析后的 Tailwind 配置对象
 */
export function extractTailwindConfig(
  designSystemHtml: string
): TailwindConfig {
  debugLog('extractTailwindConfig 开始', {
    htmlLength: designSystemHtml?.length || 0,
    htmlPreview: designSystemHtml?.substring(0, 500),
  });

  if (!designSystemHtml) {
    debugLog('extractTailwindConfig: HTML 为空，返回空配置');
    return {};
  }

  // 重置正则状态（因为使用全局标志）
  SCRIPT_REGEX.lastIndex = 0;

  // 查找所有 script 标签内容
  let match = SCRIPT_REGEX.exec(designSystemHtml);
  let scriptCount = 0;

  while (match !== null) {
    scriptCount++;
    const scriptContent = match[1];

    debugLog(`发现 script 标签 #${scriptCount}`, {
      contentLength: scriptContent.length,
      containsTailwindConfig: scriptContent.includes('tailwind.config'),
      preview: scriptContent.substring(0, 300),
    });

    const config = tryParseConfigFromScript(scriptContent);
    if (config) {
      debugLog('成功提取 Tailwind 配置', config);
      return config;
    }
    match = SCRIPT_REGEX.exec(designSystemHtml);
  }

  debugLog('extractTailwindConfig: 未找到有效配置', {
    totalScriptTags: scriptCount,
  });
  return {};
}

/**
 * 从设计系统 HTML 中提取自定义 CSS，并建立类名到规则的映射
 */
export function parseDesignSystem(
  designSystemHtml: string
): ParsedDesignSystem {
  const config = parseDesignSystemConfig(designSystemHtml);

  if (!designSystemHtml) {
    return { config };
  }

  const styleRegex = /<style[^>]*>([\s\S]*?)<\/style>/gi;
  let allCustomCSS = '';
  let styleMatch = styleRegex.exec(designSystemHtml);

  while (styleMatch !== null) {
    const customCSS = extractCustomCSS(styleMatch[1]);
    if (customCSS) {
      allCustomCSS += `${customCSS}\n`;
    }
    styleMatch = styleRegex.exec(designSystemHtml);
  }

  const trimmedCSS = allCustomCSS.trim();
  const parsedRules = trimmedCSS ? parseCSSRules(trimmedCSS) : [];

  return {
    config,
    customCSS: trimmedCSS || undefined,
    customCSSMap: parsedRules.length
      ? parseCustomCSSToMap(parsedRules)
      : undefined,
    globalCustomCSS: parsedRules.length
      ? extractGlobalCustomCSS(parsedRules)
      : undefined,
  };
}

/**
 * 尝试从 script 内容中解析 Tailwind 配置
 */
function tryParseConfigFromScript(
  scriptContent: string
): TailwindConfig | null {
  // 查找 tailwind.config = { ... }
  if (!scriptContent.includes('tailwind.config')) {
    return null;
  }

  const configMatch = scriptContent.match(CONFIG_REGEX);
  if (!configMatch?.[1]) {
    debugLog('tryParseConfigFromScript: 正则匹配失败', {
      scriptPreview: scriptContent.substring(0, 200),
    });
    return null;
  }

  const configStart = configMatch[1];
  const closingBracePos = findBalancedClosingBrace(configStart);

  if (closingBracePos === -1) {
    debugLog('tryParseConfigFromScript: 未找到闭合括号', {
      configStartPreview: configStart.substring(0, 200),
    });
    return null;
  }

  const configStr = configStart.substring(0, closingBracePos + 1);

  debugLog('tryParseConfigFromScript: 提取的配置字符串', {
    length: configStr.length,
    content: configStr,
  });

  // 验证是否是有效的对象
  if (!(configStr.startsWith('{') && configStr.endsWith('}'))) {
    debugLog('tryParseConfigFromScript: 配置字符串格式无效');
    return null;
  }

  try {
    // 使用 Function 构造器解析 JS 对象语法
    // 这比 JSON.parse 更灵活，支持无引号的键名
    const configFn = new Function(`return (${configStr})`);
    const config = configFn();

    if (config && typeof config === 'object') {
      debugLog('tryParseConfigFromScript: 解析成功', {
        hasTheme: 'theme' in config,
        hasExtend: !!config.theme?.extend,
        hasColors: !!config.theme?.extend?.colors,
        colorKeys: config.theme?.extend?.colors
          ? Object.keys(config.theme.extend.colors)
          : [],
      });
      return config as TailwindConfig;
    }
  } catch (error) {
    debugLog('tryParseConfigFromScript: 解析失败', {
      error: error instanceof Error ? error.message : String(error),
      configStr,
    });
    // eslint-disable-next-line no-console
    console.warn(
      'Failed to parse tailwind config from design system HTML:',
      error
    );
  }

  return null;
}

/**
 * 合并用户配置和默认配置
 *
 * @param userConfig - 用户自定义配置
 * @returns 合并后的最终配置
 */
export function mergeWithDefaults(userConfig: TailwindConfig): TailwindConfig {
  return {
    // 启用 preflight（base 样式），确保与 CDN 模式一致
    corePlugins: {
      preflight: true,
      ...userConfig.corePlugins,
    },
    // 合并主题配置
    theme: {
      ...userConfig.theme,
      extend: {
        ...userConfig.theme?.extend,
      },
    },
    // 保留其他配置
    ...userConfig,
  };
}

/**
 * 从设计系统 HTML 解析并返回最终配置
 *
 * @param designSystemHtml - 设计系统 HTML
 * @returns 合并默认配置后的 Tailwind 配置
 */
export function parseDesignSystemConfig(
  designSystemHtml: string
): TailwindConfig {
  const userConfig = extractTailwindConfig(designSystemHtml);
  return mergeWithDefaults(userConfig);
}

/**
 * 提取 <style> 中的自定义 CSS，仅移除 Google Fonts import
 * 与 PHP 端 extract_custom_css() 逻辑保持一致
 */
export function extractCustomCSS(styleContent: string): string {
  return styleContent
    .replace(
      /@import\s+url\s*\(\s*['"]?https:\/\/fonts\.googleapis\.com\/css2?\?[^'")\s]+['"]?\s*\)\s*;?\s*/gi,
      ''
    )
    .trim();
}

/**
 * 将 custom CSS 解析为 class -> 完整规则的映射
 */
function parseCustomCSSToMap(
  rules: ReturnType<typeof parseCSSRules>
): Map<string, string> {
  const map = new Map<string, string>();
  const classNameRegex = /\.([a-zA-Z0-9_-]+)/g;

  for (const rule of rules) {
    if (rule.type !== 'rule' || !isClassOnlySelector(rule.selector)) {
      continue;
    }

    const ruleContent = buildRuleContent(rule);
    classNameRegex.lastIndex = 0;
    let match = classNameRegex.exec(rule.selector);
    while (match !== null) {
      const className = match[1];
      const existing = map.get(className);
      if (existing !== undefined) {
        map.set(className, existing + ruleContent);
      } else {
        map.set(className, ruleContent);
      }
      match = classNameRegex.exec(rule.selector);
    }
  }

  return map;
}

function extractGlobalCustomCSS(
  rules: ReturnType<typeof parseCSSRules>
): string | undefined {
  const globalRules = rules
    .filter((rule) => {
      if (rule.type === 'at-rule') {
        return !rule.selector.startsWith('@import');
      }

      return !isClassOnlySelector(rule.selector);
    })
    .map((rule) => buildRuleContent(rule))
    .filter(Boolean)
    .join('\n')
    .trim();

  return globalRules || undefined;
}

function isClassOnlySelector(selector: string): boolean {
  return selector
    .split(',')
    .map((part) => part.trim())
    .filter(Boolean)
    .every((part) => part.startsWith('.'));
}

function buildRuleContent(
  rule: ReturnType<typeof parseCSSRules>[number]
): string {
  if (rule.type === 'at-rule') {
    return rule.content.trim();
  }

  return `${rule.selector}{${rule.content}}`.trim();
}

/**
 * 仅保留页面实际用到的 custom CSS 规则
 */
export function filterCustomCSS(
  pageHtml: string,
  customCSSMap: Map<string, string> | undefined
): string {
  if (!customCSSMap || customCSSMap.size === 0) {
    return '';
  }

  const usedClasses = new Set<string>();
  const classRegex = /class\s*=\s*["']([^"']+)["']/gi;

  let match = classRegex.exec(pageHtml);
  while (match !== null) {
    for (const cls of match[1].split(WHITESPACE_REGEX)) {
      if (cls) {
        usedClasses.add(cls);
      }
    }
    match = classRegex.exec(pageHtml);
  }

  const filteredCSS: string[] = [];
  for (const className of usedClasses) {
    const css = customCSSMap.get(className);
    if (css !== undefined) {
      filteredCSS.push(css);
    }
  }

  return filteredCSS.join('');
}
