/**
 * Parse and scope CSS rules, handling both formatted and minified CSS
 */

interface CSSRule {
  selector: string;
  content: string;
  type: 'rule' | 'at-rule';
}

interface CSSRuleWithEnd extends CSSRule {
  end: number;
}

// Top-level regex constants
const WHITESPACE_REGEX = /\s/;
const AT_RULE_NAME_REGEX = /^@[\w-]+/;

/**
 * Parse CSS into rules
 */
export function parseCSSRules(css: string): CSSRule[] {
  const rules: CSSRule[] = [];
  let current = 0;
  const length = css.length;

  while (current < length) {
    // Skip whitespace and comments
    current = skipWhitespaceAndComments(css, current);
    if (current >= length) {
      break;
    }

    // Check for at-rules
    if (css[current] === '@') {
      const atRule = parseAtRule(css, current);
      if (atRule) {
        rules.push(atRule);
        current = atRule.end;
      } else {
        current++;
      }
    } else {
      // Parse regular rule
      const rule = parseRule(css, current);
      if (rule) {
        rules.push(rule);
        current = rule.end;
      } else {
        current++;
      }
    }
  }

  return rules;
}

/**
 * Skip whitespace and comments
 */
function skipWhitespaceAndComments(css: string, start: number): number {
  let current = start;
  const length = css.length;

  while (current < length) {
    // Skip whitespace
    if (WHITESPACE_REGEX.test(css[current])) {
      current++;
      continue;
    }

    // Skip comments
    if (
      css[current] === '/' &&
      current + 1 < length &&
      css[current + 1] === '*'
    ) {
      current += 2;
      while (current + 1 < length) {
        if (css[current] === '*' && css[current + 1] === '/') {
          current += 2;
          break;
        }
        current++;
      }
      continue;
    }

    break;
  }

  return current;
}

/**
 * Parse an at-rule (@font-face, @import, etc.)
 *
 * Uses the same generic heuristic as the PHP parser:
 * if `;` appears before `{`, it's a single-line at-rule (e.g. @import);
 * otherwise it's a block at-rule (e.g. @media, @keyframes, @supports, @layer, @property).
 */
function parseAtRule(css: string, start: number): CSSRuleWithEnd | null {
  let current = start;

  // Find the rule name
  const nameMatch = css.substring(current).match(AT_RULE_NAME_REGEX);
  if (!nameMatch) {
    return null;
  }

  const ruleName = nameMatch[0];
  current += ruleName.length;

  // Generic detection: find whichever comes first — `;` or `{`
  const semicolonPos = css.indexOf(';', current);
  const bracePos = css.indexOf('{', current);

  // Single-line at-rule: `;` comes before `{` (or no `{` at all)
  if (semicolonPos !== -1 && (bracePos === -1 || semicolonPos < bracePos)) {
    return {
      selector: ruleName,
      content: css.substring(start, semicolonPos + 1),
      type: 'at-rule',
      end: semicolonPos + 1,
    };
  }

  // Block at-rule: `{` comes first
  if (bracePos === -1) {
    return null;
  }

  const braceEnd = findMatchingBrace(css, bracePos);
  if (braceEnd === -1) {
    return null;
  }

  return {
    selector: ruleName,
    content: css.substring(start, braceEnd + 1),
    type: 'at-rule',
    end: braceEnd + 1,
  };
}

/**
 * Parse a regular CSS rule
 */
function parseRule(css: string, start: number): CSSRuleWithEnd | null {
  // Find the opening brace
  const braceStart = css.indexOf('{', start);
  if (braceStart === -1) {
    return null;
  }

  // Extract selector
  const selector = css.substring(start, braceStart).trim();
  if (!selector) {
    return null;
  }

  // Find the matching closing brace
  const braceEnd = findMatchingBrace(css, braceStart);
  if (braceEnd === -1) {
    return null;
  }

  // Extract the rule content
  const content = css.substring(braceStart + 1, braceEnd).trim();

  return {
    selector,
    content,
    type: 'rule',
    end: braceEnd + 1,
  };
}

/**
 * Check if character starts a string
 */
function isStringDelimiter(char: string): boolean {
  return char === '"' || char === "'";
}

/**
 * Process character in string context
 */
function processStringContext(
  char: string,
  inString: boolean,
  stringChar: string
): { inString: boolean; stringChar: string } {
  if (!inString && isStringDelimiter(char)) {
    return { inString: true, stringChar: char };
  }
  if (inString && char === stringChar) {
    return { inString: false, stringChar: '' };
  }
  return { inString, stringChar };
}

/**
 * Process brace character
 */
function processBrace(
  char: string,
  braceCount: number
): { braceCount: number; found: boolean } {
  if (char === '{') {
    return { braceCount: braceCount + 1, found: false };
  }
  if (char === '}') {
    const newCount = braceCount - 1;
    return { braceCount: newCount, found: newCount === 0 };
  }
  return { braceCount, found: false };
}

/**
 * Find matching closing brace
 */
function findMatchingBrace(css: string, start: number): number {
  let braceCount = 0;
  let inString = false;
  let stringChar = '';
  let escaped = false;

  for (let i = start; i < css.length; i++) {
    const char = css[i];

    if (escaped) {
      escaped = false;
      continue;
    }

    if (char === '\\') {
      escaped = true;
      continue;
    }

    // Handle strings
    const stringContext = processStringContext(char, inString, stringChar);
    inString = stringContext.inString;
    stringChar = stringContext.stringChar;

    // Handle braces when not in string
    if (!inString) {
      const braceResult = processBrace(char, braceCount);
      braceCount = braceResult.braceCount;
      if (braceResult.found) {
        return i;
      }
    }
  }

  return -1;
}
